def minDays(grid):
    m, n = len(grid), len(grid[0])

    # Directions: Up, Down, Left, Right
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    # Helper to count islands using DFS
    def count_islands():
        visited = [[False]*n for _ in range(m)]
        def dfs(x, y):
            stack = [(x, y)]
            while stack:
                i, j = stack.pop()
                for di, dj in dirs:
                    ni, nj = i+di, j+dj
                    if 0 <= ni < m and 0 <= nj < n and \
                            not visited[ni][nj] and grid[ni][nj] == 1:
                        visited[ni][nj] = True
                        stack.append((ni, nj))
        cnt = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1 and not visited[i][j]:
                    visited[i][j] = True
                    dfs(i, j)
                    cnt += 1
        return cnt

    # Step 1: already disconnected?
    if count_islands() != 1:
        return 0

    # Step 2: try removing each cell
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                grid[i][j] = 0
                num = count_islands()
                grid[i][j] = 1
                if num != 1:
                    return 1

    # Step 3: can't disconnect with 1; must be 2
    return 2
